/**
 * This represents a mapping from Audience ID to a bid price adjustment.  Multiplier values must be between 0 and 10. A value of 10 represents a 900% increase in bid price (from $1 to $10 for example). A value of 0 will stop distribution for this item on the specified audience in `MAX_BID` ad groups in `CATALOG_SALES` campaigns. All audience multipliers must be set at the same time. If a multiplier is not provided it is assumed to be 1 (no bid adjustment).
 */
export interface CampaignAudienceMultipliers {
    [key: string]: number | any;

    'AUDIENCE_ID'?: string;
}
/**
 * Object describing the campaign level bid multipliers.
 */
export interface CampaignBidOptions {
    'app_type_multipliers'?: AppTypeMultipliers | null;
    'audience_multipliers'?: CampaignAudienceMultipliers;
    'placement_multipliers'?: PlacementMultipliers | null;
}
/**
 * Object describing the campaign level bid multipliers.
 */
export interface CampaignBidOptionsCreate {
    'app_type_multipliers'?: AppTypeMultipliers | null;
    'audience_multipliers'?: CampaignAudienceMultipliers;
    'placement_multipliers'?: PlacementMultipliers | null;
}
/**
 * Object describing an update to the campaign level bid multipliers.
 */
export interface CampaignBidOptionsUpdate {
    'app_type_multipliers'?: AppTypeMultipliers | null;
    'audience_multipliers'?: CampaignAudienceMultipliers;
    'placement_multipliers'?: PlacementMultipliers | null;
    /**
     * List of fields to update, only the fields in the list will be updated.
     */
    'update_mask': Array<CampaignBidOptionsUpdateUpdateMaskEnum>;
}

export const CampaignBidOptionsUpdateUpdateMaskEnum = {
    Audience: 'AUDIENCE',
    AppType: 'APP_TYPE',
    Placement: 'PLACEMENT',
    Gender: 'GENDER',
    AgeBucket: 'AGE_BUCKET'
} as const;

export type CampaignBidOptionsUpdateUpdateMaskEnum = typeof CampaignBidOptionsUpdateUpdateMaskEnum[keyof typeof CampaignBidOptionsUpdateUpdateMaskEnum];

