    public adGroupsTargetingAnalyticsGet(adAccountId: string, adGroupIds: Array<string>, startDate: string, endDate: string, targetingTypes: Array<AdsAnalyticsAdGroupTargetingType>, columns: Array<AdGroupsTargetingAnalyticsGetColumnsEnum>, granularity: Granularity, clickWindowDays?: AdGroupsTargetingAnalyticsGetClickWindowDaysEnum, engagementWindowDays?: AdGroupsTargetingAnalyticsGetEngagementWindowDaysEnum, viewWindowDays?: AdGroupsTargetingAnalyticsGetViewWindowDaysEnum, conversionReportTime?: AdGroupsTargetingAnalyticsGetConversionReportTimeEnum, attributionTypes?: Array<ConversionReportAttributionType>, reportingTimezone?: ReportingTimeZone, options?: RawAxiosRequestConfig) {
        return AdGroupsApiFp(this.configuration).adGroupsTargetingAnalyticsGet(adAccountId, adGroupIds, startDate, endDate, targetingTypes, columns, granularity, clickWindowDays, engagementWindowDays, viewWindowDays, conversionReportTime, attributionTypes, reportingTimezone, options).then((request) => request(this.axios, this.basePath));
    }

